module top_module(
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdusedw
);input aclr;
    input [15:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output reg [31:0] q;
    output reg [7:0] rdusedw;

    reg [31:0] sub_wire0;
    reg [7:0] sub_wire1;

    always @ (posedge wrclk or negedge aclr) begin
        if (~aclr) begin
            sub_wire0 <= 0;
            sub_wire1 <= 0;
        end else if (wrreq) begin
            sub_wire0 <= {sub_wire0[15:0], data};
            sub_wire1 <= sub_wire1 + 1;
        end
    end

    always @ (posedge rdclk or negedge aclr) begin
        if (~aclr) begin
            q <= 0;
            rdusedw <= 0;
        end else if (rdreq && sub_wire1 > 0) begin
            q <= {sub_wire0[31:16], sub_wire0[15:0]};
            sub_wire1 <= sub_wire1 - 1;
            rdusedw <= sub_wire1;
        end
    end

endmodule

