module top_module(
  input clk,
  input rst,
  input [7:0] addr,
  input we,
  input [7:0] din,
  output reg [7:0] dout // Changed to reg type
);// Define memory array with 256 words of 8 bits each
  reg [7:0] memory [0:255];

  // Define internal signals for address and data
  reg [7:0] addr_reg;
  reg [7:0] din_reg;
  reg [7:0] dout_reg; // Changed to reg type for storing output

  // Synchronize address and data inputs with the clock
  always @(posedge clk) begin
    if (rst) begin
      addr_reg <= 8'h00;
      din_reg <= 8'h00;
    end else begin
      addr_reg <= addr;
      if (we) begin
        din_reg <= din;
      end
    end
  end

  // Read or write data from/to memory based on we input
  always @(*) begin
    if (we) begin
      memory[addr_reg] <= din_reg;
    end else begin
      dout_reg = memory[addr_reg]; // Using non-blocking assignment
    end
  end

  // Synchronize output data with the clock
  always @(posedge clk) begin
    if (rst) begin
      dout <= 8'h00;
    end else begin
      dout <= dout_reg; // dout is now a reg type
    end
  end

endmodule

