module up_down_counter(
    input clk,
    input reset,
    input up_down,
    output reg [9:0] count
    );

    always @(posedge clk) begin
        if (reset)
            count <= 10'b0000000000;
        else if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end
endmodule

