description:
Design a 24-bit counter-based blink circuit that produces a one-bit output. The output toggles every 2^24 clock cycles, effectively creating a slow blink signal. The counter is incremented on each clock edge when not in reset; upon reset, the counter resets to zero. The most significant bit of the counter, `counter_q[23]`, is used as the output signal to indicate the blink state.
module top_module(
    input clk,
    input rst,
    output out
    );

code:
module top_module(
    input clk,
    input rst,
    output out
    );reg [23:0] counter_d, counter_q;

assign out = counter_q[23];

always @(counter_q) begin
    counter_d = counter_q + 1'b1;
end

always @(posedge clk) begin
    if (rst) begin
        counter_q <= 23'b0;
    end else begin
        counter_q <= counter_d;
    end
end

endmodule

