Implement the Verilog module based on the following description.
Design an 8-bit parallel-in/serial-out (PISO) shift register with enable and asynchronous load.
// (1) enable: Enables the shift register. Active high.
// (2) load: Asynchronous load of the parallel data. Active high.
// (3) parallel_in: 8-bit parallel data input.
// (4) clk: Clock signal.
// (5) serial_out: Serial data output.
module piso_shift_register(
	input clk,
	input enable,
	input load,
	input [7:0] parallel_in,
	output reg serial_out);

code:
module piso_shift_register(
	input clk,
	input enable,
	input load,
	input [7:0] parallel_in,
	output reg serial_out);reg [7:0] shift_reg;
always @(posedge clk or posedge load) begin
	if (load)
		shift_reg <= parallel_in;
	else if (enable)
		shift_reg <= {shift_reg[6:0], 1'b0};
end

always @(posedge clk or posedge load) begin
	if (load)
		serial_out <= parallel_in[7];
	else if (enable)
		serial_out <= shift_reg[7];
end
endmodule

