module top_module(start, d, en, clk, clear_b, q);input [24:0]d;
	input start, en, clk, clear_b;
	output q;

	reg [24:0] out;
	always @(posedge clk, negedge clear_b)
	begin
		if (clear_b == 1'b0)
			out <= 25'b1;
		else if (start == 1'b0)
			out <= d;
		else if (en == 1'b1)
			begin
				if (out == 25'b0)
					out <= d;
				else
					out <= out - 1'b1;
			end
	end
   assign q = (out == 25'b0) ? 1 : 0;endmodule

