module digital_lock (
	input clk,
	input resetn,
	input key,
	output unlock);

	parameter IDLE=0, S1=1, S10=2, S101=3, S1010=4;
	reg [2:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = key ? S1 : IDLE;
			S1: next_state = key ? S1 : S10;
			S10: next_state = key ? S101 : IDLE;
			S101: next_state = key ? S1 : S1010;
			S1010: next_state = key ? S1 : IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign unlock = (state == S1010);
endmodule

