module top_module(
  input clk,
  input areset,
  input pedestrian_button,
  output reg red_light,
  output reg yellow_light,
  output reg green_light,
  output reg walk_signal
);// Define the states
  parameter STATE_0 = 2'b00;
  parameter STATE_1 = 2'b01;
  parameter STATE_2 = 2'b10;
  parameter STATE_3 = 2'b11;

  // Define the current state
  reg [1:0] current_state;

  // Define the next state
  reg [1:0] next_state;

  // State machine logic
  always @(posedge clk or negedge areset) begin
    if (areset == 1'b0) begin
      current_state <= STATE_0;
      red_light <= 1'b1;
      yellow_light <= 1'b0;
      green_light <= 1'b0;
      walk_signal <= 1'b0;
    end else begin
      current_state <= next_state;

      case (current_state)
        STATE_0: begin
          red_light <= 1'b1;
          yellow_light <= 1'b0;
          green_light <= 1'b0;
          walk_signal <= 1'b0;
          if (pedestrian_button == 1'b1) begin
            next_state <= STATE_3;
          end else begin
            next_state <= STATE_1;
          end
        end
        STATE_1: begin
          red_light <= 1'b1;
          yellow_light <= 1'b0;
          green_light <= 1'b0;
          walk_signal <= 1'b1;
          if (pedestrian_button == 1'b1) begin
            next_state <= STATE_3;
          end else begin
            next_state <= STATE_2;
          end
        end
        STATE_2: begin
          red_light <= 1'b0;
          yellow_light <= 1'b1;
          green_light <= 1'b0;
          walk_signal <= 1'b0;
          next_state <= STATE_3;
        end
        STATE_3: begin
          red_light <= 1'b0;
          yellow_light <= 1'b0;
          green_light <= 1'b1;
          walk_signal <= 1'b1;
          next_state <= STATE_0;
        end
      endcase
    end
  end

endmodule

