Implement the Verilog module based on the following description.
Build a 4-bit binary counter with a count enable signal and asynchronous active low reset signal.
// (1) reset_n: Asynchronously resets the counter to 4'b0000 when low.
// (2) count_enable: Enables counting when high.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input count_enable,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input count_enable,
    output reg [3:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (count_enable) begin
            // Increment the counter if count_enable is high
            q <= q + 1;
        end
    end

endmodule

