module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter W=0, X=1, Y=2, Z=3;

    always_comb begin
		case (state)
			W: next_state = (in1 || in2) ? Y : X;
			X: next_state = (in1 || in2) ? Z : Y;
			Y: next_state = (in1 || in2) ? W : Z;
			Z: next_state = (in1 || in2) ? X : W;
		endcase
    end

	assign out = (state==X) || (state==Z);

endmodule

