description:
Design a control unit for an Arithmetic Logic Unit (ALU) that produces a 3-bit ALU control signal based on a 2-bit ALU operation code (`ALUOp_i`) and a 6-bit function code (`funct_i`). The module decodes the input signals to determine the appropriate operation: for `ALUOp_i` of `01`, it sets the control output to `010`; for `ALUOp_i` of `11`, it distinguishes among various functions defined in `funct_i`, producing different control outputs for specific function codes. If none of the defined cases are matched, the output is set to an undefined state.
module top_module(
	funct_i,
	ALUOp_i,
	ALUCtrl_o
);

code:
module top_module(
	funct_i,
	ALUOp_i,
	ALUCtrl_o
);input	[1:0]		ALUOp_i;
input	[5:0]		funct_i;
output	[2:0]		ALUCtrl_o;

assign	ALUCtrl_o	=	(ALUOp_i == 2'b01) ? 3'b010 :
						((ALUOp_i == 2'b11) && (funct_i[3:0] == 4'b0000)) ? 3'b010 :
						((ALUOp_i == 2'b11) && (funct_i[3:0] == 4'b1000)) ? 3'b100 :
						((ALUOp_i == 2'b11) && (funct_i[3:0] == 4'b0010)) ? 3'b110 :
						((ALUOp_i == 2'b11) && (funct_i[3:0] == 4'b0100)) ? 3'b000 :
						((ALUOp_i == 2'b11) && (funct_i[3:0] == 4'b0101)) ? 3'b001 :
						3'bx;


endmodule

