code:
module top_module(
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);parameter WIDTH = 12;
    parameter DEPTH = 16;

    input aclr;
    input [WIDTH-1:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [WIDTH-1:0] q;
    output rdempty;
    output wrfull;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [WIDTH-1:0] q_reg;
    reg [4:0] wrptr;
    reg [4:0] rdptr;
    reg [4:0] count;
    wire [4:0] next_wrptr;
    wire [4:0] next_rdptr;
    wire [4:0] next_count;

    assign rdempty = (count == 0);
    assign wrfull = (count == DEPTH);

    always @(posedge wrclk or negedge aclr) begin
        if (!aclr) begin
            wrptr <= 0;
            count <= 0;
        end else if (wrreq && !wrfull) begin
            mem[wrptr] <= data;
            wrptr <= next_wrptr;
            count <= next_count;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (!aclr) begin
            rdptr <= 0;
        end else if (rdreq && !rdempty) begin
            q_reg <= mem[rdptr];
            rdptr <= next_rdptr;
            count <= next_count;
        end
    end

    assign q = q_reg;

    assign next_wrptr = (wrptr == DEPTH-1) ? 0 : wrptr + 1;
    assign next_rdptr = (rdptr == DEPTH-1) ? 0 : rdptr + 1;
    assign next_count = count + wrreq - rdreq;

endmodule

