description:
Design a Verilog module for a 2-bit gray code counter with an asynchronous reset. The counter should increment its value in gray code sequence on each positive clock edge. If reset is high, the counter should reset to 2'b00.
module gray_code_counter (
    input clk,
    input reset,
    output reg [1:0] q
);

code:
module gray_code_counter (
    input clk,
    input reset,
    output reg [1:0] q
);always @(posedge clk or posedge reset) begin
        if (reset)
            q <= 2'b00;
        else begin
            case (q)
                2'b00: q <= 2'b01;
                2'b01: q <= 2'b11;
                2'b11: q <= 2'b10;
                2'b10: q <= 2'b00;
            endcase
        end
    end

endmodule

